row(2, 31, 'MATERIAL', f'AND THE LORD SAID TO ME: SEE, I HAVE BEGUN TO GIVE SIHON AND HIS LAND BEFORE YOU; BEGIN TO POSSESS HIS LAND. {HP(2, 31, (("ויאמר", "יהוה", "אלי"), "and the LORD said to me — the fourth frame (computed)"), (("ראה", "החלתי", "תת", "לפניך", "את", "סיחן"), "see, I have begun to give before you Sihon — one seat (computed)"), (("החל", "רש", "לרשת", "את", "ארצו"), "begin, possess, to possess his land (computed)"))} → {AP(2, 31, (("חזי", "שריתי", "לממסר", "קדמך", "ית", "סיחן"), "see, I have begun to deliver before you Sihon — \'I have begun\' one seat (computed)"), (("שרי", "לתרכותיה", "למירת", "ית", "ארעיה"), "begin to drive him out, to inherit his land"))}')
